workbench.on('onCalculate', (data) => {
  if(data.type === 'thread') {
    // 自动计算螺纹小径底孔 = 大径 - 螺距 * 1.0825
    data.results.minorDiameter = data.inputs.major - data.inputs.pitch * 1.0825;
  }
  return data;
});

